import{_ as e,o as t,c as s,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const m=JSON.parse('{"title":"PhyEduVideo: A Benchmark for Evaluating Text-to-Video Models for Physics Education","description":"","frontmatter":{"title":"PhyEduVideo: A Benchmark for Evaluating Text-to-Video Models for Physics Education","arxiv":"2601.00943","date":"2026-01-02","authors":"Megha Mariam K.M, Aditya Arun, Zakaria Laskar, C.V. Jawahar","categories":"cs.CV","topics":"物理感知视频生成, 教育视频评测, T2V benchmark","outline":[2,2]},"headers":[],"relativePath":"papers/2601.00943.md","filePath":"papers/2601.00943.md","lastUpdated":null}'),r={name:"papers/2601.00943.md"};function o(i,a,l,h,d,p){return t(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="phyeduvideo-a-benchmark-for-evaluating-text-to-video-models-for-physics-education" tabindex="-1">PhyEduVideo: A Benchmark for Evaluating Text-to-Video Models for Physics Education <a class="header-anchor" href="#phyeduvideo-a-benchmark-for-evaluating-text-to-video-models-for-physics-education" aria-label="Permalink to &quot;PhyEduVideo: A Benchmark for Evaluating Text-to-Video Models for Physics Education&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2601.00943" target="_blank" rel="noreferrer">2601.00943</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-01-02</td></tr><tr><td><strong>作者</strong></td><td>Megha Mariam K.M, Aditya Arun, Zakaria Laskar, C.V. Jawahar</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 60 个物理概念拆成 205 个「教学点」提示词，用 SA/PC/MS/TF 四维评估 T2V 模型能不能真正把一个物理概念讲清楚，而非只是看起来真实。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv v1 全文（WACV 2026 接收）。正文称概念来自「七大经典物理领域」，但实际只列出六个（Mechanics 38.33%、Electromagnetism 20.00%、Thermodynamics 16.67%、Fluids 10%、Optics 8.33%、Waves &amp; Oscillations 6.67%，合计 100%），本文按六个领域理解；附录 A 写「六个模型」但实际评测五个，同属笔误。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>物理教学视频贵在「把看不见的东西画出来」：电场线、热流、相对运动。制作一条这样的视频需要教师想清楚讲解逻辑、设计视觉隐喻、再找人做动画，成本极高。T2V 模型看起来是天然的替代方案——输入一句话，输出一段动画。问题在于，现有 T2V 评测体系根本没有回答教育场景真正关心的问题。</p><p>作者把这个缺口定义为：<strong>视觉合理性 ≠ 教学有效性</strong>。一段视频可以帧间平滑、无闪烁、物体不变形，同时把楞次定律画反。PhyEduVideo 要问的是「这段视频能不能教会人」，而不是「这段视频看起来像不像真的」。这个重构值得重视，因为它把评测单元从「一个物理定律」下沉到「一个教学点」（teaching point）——牛顿第一定律被拆成静止物体、匀速运动、惯性、受力加速四个点，每个点单独出题、单独打分。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>作者点名了两类前人工作。第一类是通用视频质量 benchmark：VBench 及其后续 VBench++/VBench 2.0 建立了包含 prompt adherence、空间一致性、时间一致性的分层框架，VBench 2.0 加入了 commonsense reasoning 和物理真实性；T2VCompBench 关注组合泛化；DEVIL 关注运动动态。这些确实把「视频好不好看」量化得很细，但它们的 prompt 来自开放语料，与任何课程结构无关。</p><p>第二类是物理专用 benchmark：VideoPhy 提出了 Semantic Adherence（SA）与 Physical Commonsense（PC），VideoPhy-2 增补 Physical Rules 维度；Physics-IQ 用真实视频考察直觉物理；PhyGenBench 用 27 条物理定律的 160 条提示词覆盖力学、热学、光学，并用 LLM 评估器打分；T2VPhysBench 提供 84 条提示词覆盖十二条定律。作者对这批工作的批评很精确：它们检验的是「视频是否遵守物理定律」，而教学需要的是「视频是否把物理概念讲清楚」。这两件事在电磁学这类领域上会直接分叉——一段电流通过导线的视频可以完全不违反任何物理定律（画面里什么都没发生），但对教学毫无价值，因为它没有把不可见的场变成可见的东西。这就是 X 之前没被考虑的原因：物理 benchmark 的设计者默认「物理正确」是终点，而教学要求「物理正确且可被感知」。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇论文之前，社区已经知道三件事：T2V 模型的运动平滑度和时间稳定性在 2024–2025 年间基本被解决（VBench 上这两项分数普遍逼近饱和）；物理常识仍然是短板（VideoPhy 系列反复证实）；教育 AI 的落地形态仍以文本为主（Khan Academy + GPT-4、Socratic by Google），多模态教学内容生成几乎空白。</p><p>一个认真的研究者从这三点出发会问：既然视觉质量已经不是瓶颈，那么阻碍 T2V 进课堂的是什么？直接拿 VideoPhy 跑一遍会发现分数不算低，但把生成的视频拿给物理老师看，老师会说「这个不能用」。于是问题变成：现有指标为什么与教师判断不一致？答案是评测单元错了——物理定律太粗，一条定律对应多种教学情境，模型在其中一种上成功就能拿分。把评测单元换成教学点，粒度立刻对齐了教学实践，指标与人类判断的相关性也应该随之提升。论文的核心实验（§7）正是在验证这条推理链。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>物理教学视频的失败模式不是「不真实」，而是「讲错了或没讲到」。把一个概念拆成教师实际会讲的若干个教学点，每个点配一条自足的可视化提示词，评测就从「模型会不会画物理」变成「模型会不会讲物理」。这个粒度切换本身就是方法：它让评估器有明确的判断对象（这一帧里该出现的物体和该发生的动作是什么），从而使自动打分与人类打分显著对齐。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>benchmark 构建分四步，作者用 Gemma-3 做自动化、用物理专家做过滤：</p><ol><li><strong>概念抽取</strong>：用 Gemma-3 从 K-12 与本科物理课程中抽取经典物理概念候选集。</li><li><strong>人工过滤</strong>：物理专家保留「教学必要且可视化」的概念，剔除拉格朗日力学、张量微积分、复变积分这类抽象或高度数学化的主题，最终留下 60 个概念。</li><li><strong>拆解为教学点</strong>：每个概念拆成 1–5 个教学点。例如「牛顿第一定律」→ 静止物体保持静止、运动物体保持匀速、惯性、受力才产生加速度。</li><li><strong>提示词生成与精修</strong>：每个教学点先由 Gemma-3 生成候选提示词，再人工改写。最终 205 条提示词，平均长度 16–45 词。</li></ol><p>评测端有四个维度。SA 用 InternVL3.5 打 0–3 分，拆成 object score（0/1/2：关键物体缺失/部分/齐全）与 action score（0/1：主要动作是否呈现）。PC 分三段：关键物理现象检测（抛体是否画成抛物线而非直线）、物理顺序验证（摆先被释放再摆动，用 LLaVA-Interleave 判定）、整体自然度（用 GPT 生成 fantastical / clearly unrealistic / slightly unrealistic / realistic 四档描述，再用 InternVideo2 把视频归到最接近的一档）。MS 与 TF 沿用 VBench 定义，度量运动连续性与帧间视觉属性稳定性。</p><p>一个完整例子：概念「相对运动」→ 教学点 T04「两辆玩具车以相同速度并排行驶」→ 提示词送入五个 T2V 模型 → 生成视频 → InternVL3.5 判断两辆车是否都出现、是否并排同速 → LLaVA-Interleave 判断事件顺序 → InternVideo2 归档自然度。论文图 1 明确指出 T04 上模型生成的两车并未保持同速，这正是 SA 该扣分而 MS/TF 不会扣分的典型情形。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。唯一的定量机制是人机一致性检验中使用的 Spearman 秩相关 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 与 Kendall 秩相关 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>，两者都直接取自标准定义，论文未做任何改造。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：新指标是否比现有物理指标更贴近人类判断？</strong> 作者对 500 段视频做人工评估，标注者具备 12 年级以上物理背景。结论是 PhyEduVideo 在 SA 上取得 Spearman 0.509 / Kendall 0.462，比 VideoPhy 分别高 0.071 与 0.122；在 PC 上取得 0.392 / 0.363，而 VideoPhy 仅 0.008 / 0.006，绝对提升 0.384 与 0.357。PC 这一项的差距极其悬殊——VideoPhy 的物理常识分数与人类判断几乎完全不相关。这是全文最强的证据。分领域看，热力学的相关性最高，电磁学与光学最低。</p><p><strong>问题二：当前 T2V 模型在物理教学上处于什么水平？</strong> 评测 CogVideoX-5B、Wan2.1、VideoCrafter2、Video-MSG、PhyT2V 五个模型。MS 与 TF 普遍在 0.85 以上（Wan2.1、Video-MSG 达 0.99），SA/PC 则明显偏低。平均而言 Wan2.1 最强（SA 0.83 / PC 0.60），PhyT2V 次之（0.78 / 0.60），VideoCrafter2 垫底（0.62 / 0.50）。分领域：流体与光学最好（SA 最高 0.90、PC 最高 0.71），力学次之（SA &gt; 0.75、PC &gt; 0.50），热力学与电磁学最差（VideoCrafter2 在热力学上 SA 0.51 / PC 0.38，电磁学上多数模型 PC 低于 0.50）。作者据此提出「reasoning–perception gap」：感知层面早已饱和，推理层面仍未起步。Video-MSG 这类靠 MLLM 做布局规划的 training-free 方法在视觉指标上很强却没能提升 PC，说明组合式控制不足以带来物理理解。</p><p><strong>问题三：自动评估器错在哪？</strong> 附录 C 的错配分析显示，PhyEduVideo 在简单场景（推购物车）与人类完全一致，在复杂场景系统性<strong>高估</strong>。旋转线圈一例中人类给 SA 0.34 / PC 0.34，模型给 1.0 / 0.67；行星轨道、磁场中带电粒子等场景同样高估。作者的解释是评估器检测到了「有运动、有场」就给分，没有检验轨道速度变化、圆周轨迹这类细节。这是个诚实且重要的自曝。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：现有 T2V 物理 benchmark 检验「是否违反物理定律」，但教育场景真正需要的是「是否把概念讲清楚」，二者在电磁学、热力学这类抽象领域会分叉。PhyEduVideo 把 60 个经典物理概念拆成 205 个教学点提示词，用 SA/PC/MS/TF 四维打分。人机一致性实验显示它在 PC 维度上把 Spearman 相关从 VideoPhy 的 0.008 提到 0.392。五个模型的评测结果暴露出清晰的「感知饱和、推理停滞」格局：MS/TF 普遍 0.9+，SA/PC 却在 0.5–0.8 徘徊。自动评估器本身在复杂场景系统性高估，是这套 benchmark 当前最大的软肋。</p><p><strong>3 句话版</strong>：把物理概念拆成教学点，让 T2V 评测从「像不像真的」转向「能不能教会人」。新指标在物理常识维度上与人类判断的相关性远高于 VideoPhy。当前模型在力学、流体、光学尚可，在电磁学与热力学上失败，因为这些领域的核心实体不可见。</p><p><strong>1 句话版</strong>：教学点粒度的物理教育 benchmark，揭示了 T2V 模型「画面已经够好、物理还没入门」的真实状态。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>用 InternVL3.5、LLaVA-Interleave、InternVideo2 组成的自动评估流水线，其物理判别能力足以支撑对物理教学质量的裁决</strong>。这个假设一旦不成立，整套 benchmark 的排名与结论都失去意义。</p><p>论文自己提供了它可能不成立的证据：附录 C 明确记录了评估器在旋转线圈、行星轨道、磁场中带电粒子等场景上给出远高于人类的分数，作者归因为「检测到了大致运动或场的存在，却没捕捉到轨道速度变化、圆周轨迹等细节」。这正是评测最需要区分能力的地方——简单场景所有模型都对，难场景才拉开差距，而评估器恰恰在难场景失效。更微妙的是，被评测的能力（理解电磁与热力学）与评估器自身的能力来自同一类视觉语言模型，它们很可能共享同样的盲区：如果 InternVL3.5 自己就分不清正确与错误的电场线，它给出的电磁学分数就是噪声。论文用 Spearman 0.392 的 PC 相关性作为辩护，但这个数值本身只说明「比完全不相关好」，离可信裁决还有距离。作者没有报告分领域的评估器可靠性下界，也没有做「只用人工标注重新排名，模型顺序是否改变」的稳健性检验。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可完成的验证，目标是检验上一节的脆弱假设：</p><ul><li><strong>数据</strong>：从 PhyEduVideo 公开仓库（github.com/meghamariamkm/PhyEduVideo）取电磁学与热力学两个最弱领域的全部提示词，约 40 条。</li><li><strong>实现</strong>：只跑两个模型（Wan2.1 与 VideoCrafter2，二者在论文中差距最大），每条提示词生成 3 个 seed。</li><li><strong>测量</strong>：三路打分——论文的自动流水线、一个未参与 benchmark 设计的第三方 VLM（如 Qwen2.5-VL）、两名物理专业标注者。计算三者两两的 Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>。</li><li><strong>判据</strong>：若自动流水线与人类的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 在这两个领域低于 0.2，同时两个模型的相对排名在人类打分下发生翻转，则说明论文在最弱领域的结论不可依赖；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 稳定在 0.35 以上且排名一致，则假设成立。</li></ul><p>这个方案不需要复现任何生成模型的训练，成本主要在推理与标注。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个<strong>替代解释</strong>：论文观察到的「电磁学、热力学最差」可能完全不是模型的物理理解问题，而是<strong>提示词可视化难度与评估器判别难度的混淆</strong>。</p><p>具体设计：为每个领域构造一组「对照提示词」，其物理内容完全相同，但把不可见实体替换为可见代理——把「磁感线」换成「铁屑沿磁感线排列」，把「热量传递」换成「温度敏感变色涂料由蓝变红」。如果模型在对照组上的 SA/PC 大幅回升，那么论文测到的就不是「模型不懂电磁学」，而是「模型不会发明可视化隐喻」，这是两种完全不同的能力缺陷，对应完全不同的改进方向（前者需要物理先验注入，后者需要教学表征的监督数据）。</p><p>第二重攻击针对指标的可 hack 性：MS 与 TF 在近静态视频上会给出接近满分（这一点在驾驶世界模型评测中已被 DrivingGen 等工作明确指出）。论文报告所有模型 MS/TF 均在 0.85 以上，但没有报告生成视频的实际运动幅度。一个只输出几乎静止画面的模型会同时拿到高 MS、高 TF 和不算太差的 PC（因为静止不违反物理），却毫无教学价值。论文没有防守这一点。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：PhyEduVideo 评的是「视频是否正确呈现教学点」，但教学的真正目标是「学习者是否理解了」。视频正确与学习发生之间没有必然联系——一段技术上完全正确的电磁感应动画可能因为视角、节奏、强调重点的选择而完全无法被初学者理解。当前所有指标都是 video-centric，没有一个是 learner-centric。</p><p><strong>新 framing</strong>：把 benchmark 的目标函数从「视频保真度」换成「概念获得量」，即用学习者（可以是人，也可以是被冻结的学生模型）在观看视频前后的概念测验分数差作为唯一指标。这不是给现有 benchmark 加一个维度，而是换掉整个评价对象：生成模型不再被要求画对，而被要求教会。</p><p><strong>可借鉴的相邻工具</strong>：教育测量学中的 item response theory 提供了把「测验分数差」归因到具体概念点的成熟框架；RLHF 中的 reward model 训练范式可以直接复用——把「学生模型看完视频后答题正确率」当作 reward，对 T2V 做 post-training。</p><p><strong>第一个实验</strong>：取 PhyEduVideo 的 60 个概念，为每个概念编写 4 道选择题。招募或模拟两组学习者：一组只读文字描述，一组看模型生成的视频加同样的文字。测量两组的答题正确率差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span>。核心问题是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 与论文的 SA/PC 分数是否相关——如果不相关，说明「视频正确」与「教学有效」确实是两件事，本文的 benchmark 需要被替换而非扩展；如果强相关，说明视频保真度是学习效果的良好代理，本文的路线得到独立验证。无论哪个结果，都比继续在保真度指标上加维度更有信息量。</p>',46)])])}const g=e(r,[["render",o]]);export{m as __pageData,g as default};
